(function(){
'use strict';
const Q=window.CCGQuest,canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false}),loading=document.getElementById('loading');
const input=new Q.Input(canvas),assets=new Q.AssetLoader(),audio=new Q.AudioEngine();
ctx.imageSmoothingEnabled=true;
const S={mode:'loading',returnMode:'title',practice:false,stage:0,elapsed:0,score:0,lives:3,mult:1,best:0,time:0,last:0,entities:[],shots:[],particles:[],pending:[],boss:null,fighter:null,inv:null,maze:null,beadTime:0,transition:null,buttons:[],shake:0,flash:0,toast:null,itemSpawn:0,powerSpawn:0,patternTimer:0,patternIndex:0,stageGrace:0,shieldLowBeep:0,hazardReleaseAt:0,enemySpawn:0,beadEnemyTimer:0,beadLeftShots:0};
const P={x:250,y:0,w:78,h:132,vx:0,vy:0,ground:true,face:1,hp:100,max:100,inv:0,fire:0,duck:false,shield:0,speed:0,double:0,anim:0,attack:null,attackT:0,attackLen:0,hitLatch:false,stun:0,combo:0,comboUntil:0};
P.y=Q.GROUND-P.h;
const ACH=new Q.Achievements(a=>{S.toast={text:a.name,xp:a.xp,until:Q.now()+3200};audio.sfx('unlock');});S.best=ACH.profile.best||0;
const now=()=>Q.now(),clamp=Q.clamp,rand=Q.rand,pick=Q.pick,rhit=Q.rectHit;
function rr(x,y,w,h,r,fill=true,stroke=false){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill)ctx.fill();if(stroke)ctx.stroke();}
function text(t,x,y,size=20,col='#fff',align='left',weight=800){ctx.fillStyle=col;ctx.font=`${weight} ${size}px Consolas,monospace`;ctx.textAlign=align;ctx.fillText(t,x,y);}
function bar(x,y,w,p,c){ctx.fillStyle='rgba(0,0,0,.78)';rr(x,y,w,14,6);ctx.fillStyle='#252334';rr(x+2,y+2,w-4,10,4);ctx.fillStyle=c;rr(x+2,y+2,(w-4)*clamp(p,0,1),10,4);}
function focus(){canvas.focus({preventScroll:true});try{scrollTo({top:0,left:0,behavior:'instant'});}catch(_e){scrollTo(0,0);}}
function mode(m){S.mode=m;S.buttons=[];focus();}
function load(){const jobs=[];['bedroom','budget','christmas','amiga','guru','beads','fighter','invaders','maze'].forEach(k=>{jobs.push(assets.optionalImage('bg_'+k,`assets/backgrounds/${k}.svg`));jobs.push(assets.optionalImage('custom_bg_'+k,Q.customAsset?.('backgrounds',k)));});jobs.push(assets.optionalImage('mascot_source','/resources/images/ccgamer-logo.png'));for(const scene of ['bedroom','beads','budget','fighter','invaders','christmas','maze','amiga','guru'])for(const suffix of ['Back','Mid','Front'])jobs.push(assets.optionalImage('layer_'+scene+suffix,Q.customAsset?.('layers',scene+suffix)));for(const key of ['player','fighter','enemy','bossBedroom','bossBudget','bossChristmas','bossAmiga','bossGuru'])jobs.push(assets.optionalImage('sheet_'+key,Q.customAsset?.('spritesheets',key)));['mascot','head','avatar','body','arm','leg'].forEach(k=>jobs.push(assets.optionalImage('player_'+k,Q.customAsset?.('player',k))));['bedroom','budget','christmas','amiga','guru'].forEach(k=>{jobs.push(assets.optionalImage('boss_'+k,Q.customAsset?.('bosses',k)));jobs.push(assets.optionalImage('hazard_'+k,Q.customAsset?.('hazards',k)));});['tape','disk','zzap','joystick'].forEach(k=>jobs.push(assets.optionalImage('item_'+k,Q.customAsset?.('collectibles',k))));['shield','speed','double'].forEach(k=>jobs.push(assets.optionalImage('power_'+k,Q.customAsset?.('powers',k))));['enemy','enemyPunch','enemyKick','enemyHit'].forEach(k=>jobs.push(assets.optionalImage('fighter_'+k,Q.customAsset?.('fighter',k))));['alien1','alien2','alien3','alien4','alien5','ship','bunker','enemyShot','playerShot'].forEach(k=>jobs.push(assets.optionalImage('invader_'+k,Q.customAsset?.('invaders',k))));return Promise.all(jobs);}
function clearWorld(){S.entities=[];S.shots=[];S.particles=[];S.pending=[];S.boss=null;S.fighter=null;S.inv=null;S.maze=null;S.hazardReleaseAt=S.time;}
function resetPlayer(){Object.assign(P,{x:250,y:Q.GROUND-P.h,vx:0,vy:0,hp:100,inv:0,fire:0,duck:false,shield:0,speed:0,double:0,attack:null,attackT:0,hitLatch:false,stun:0,combo:0,comboUntil:0,face:1});}
function reset(){S.score=0;S.lives=3;S.mult=1;clearWorld();resetPlayer();}
function transition(title,sub,next,dur=1.8){S.transition={title,sub,next,t:0,dur};mode('transition');}
function startQuest(){audio.start();ACH.startRun();S.practice=false;reset();enterStage(0);}
function practice(id){audio.start();S.practice=true;reset();if(id==='beads')startBeads();else if(id==='fighter')startFighter();else if(id==='invaders')startInvaders();else if(id==='maze')startMaze();else enterStage(Math.max(0,Q.STAGES.findIndex(s=>s.id===id)));}
function enterStage(i){S.stage=i;S.elapsed=0;S.patternTimer=1.3;S.patternIndex=0;S.itemSpawn=.8;S.powerSpawn=7.5;S.enemySpawn=i===0?6.2:Math.max(3.2,5.4-i*.45);S.stageGrace=1.5;clearWorld();P.x=i===2?1260:250;P.y=Q.GROUND-P.h;P.vx=P.vy=0;P.face=i===2?-1:1;P.hp=Math.max(65,P.hp);P.inv=now()+1100;P.stun=0;const st=Q.STAGES[i];audio.setTheme(st.music,false,st.id);transition(st.name,st.subtitle,'stage',1.8);if(!S.practice&&i===3)ACH.flag('amiga');if(!S.practice&&i===4)ACH.flag('guru');}
function afterBoss(){if(S.practice){transition('PRACTICE COMPLETE','Score not submitted.','title',1.8);return;}if(S.stage===0)startBeads();else if(S.stage===1)startFighter();else if(S.stage===2)startMaze();else if(S.stage===3)enterStage(4);else win();}
function startBeads(){clearWorld();S.beadTime=0;S.patternTimer=.9;S.beadEnemyTimer=3.8;S.beadLeftShots=0;P.x=240;P.y=Q.GROUND-P.h;P.vx=P.vy=0;P.face=1;P.hp=Math.max(65,P.hp);audio.setTheme(0,false,'beads');transition('ELECTRIC BEAD RUN','28 SECONDS. JUMP, DUCK AND SHOOT YOUR WAY THROUGH.','beads',1.7);}
function startFighter(){clearWorld();S.fighter={x:1150,y:Q.GROUND-154,w:96,h:154,hp:100,max:100,vx:0,vy:0,ground:true,think:.14,cool:.38,guard:0,attack:null,attackT:0,attackLen:0,hitLatch:false,stun:0,face:-1,message:'SPECIAL MOVES: STILL MISSING',messageT:2,boutTime:45,ai:'read',aiT:0};P.x=330;P.y=Q.GROUND-P.h;P.hp=100;P.vx=P.vy=0;P.face=1;P.attack=null;P.stun=0;P.combo=0;audio.setTheme(1,true,'fighter');transition('THE 36% CONVERSION BOUT','TIER-TEX HAS LEARNED A FEW DIRTY TRICKS.','fighter',1.9);}
function startInvaders(){clearWorld();const aliens=[];for(let r=0;r<5;r++)for(let c=0;c<9;c++)aliens.push({x:330+c*105,y:145+r*62,w:56,h:36,alive:true,row:r,col:c,phase:(r+c)%2});const bunkers=[330,650,970,1290].map(x=>({x,y:686,w:120,h:34,hp:7,max:7}));S.inv={shipX:800,shield:3,invuln:0,fire:0,dir:1,speed:72,aliens,shots:[],enemyCool:.58,drop:0,elapsed:0,bunkers};audio.setTheme(3,false,'invaders');transition('ALIEN FORMATION','45 ALIENS. NO AUTOFIRE. THEY SHOOT BACK A LOT.','invaders',1.9);}
function makeMaze(){const W=21,H=13,walls=new Set();for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(x===0||y===0||x===W-1||y===H-1)walls.add(`${x},${y}`);[[5,2,4],[5,7,10],[10,2,5],[10,8,10],[15,2,4],[15,7,10]].forEach(([x,a,b])=>{for(let y=a;y<=b;y++)walls.add(`${x},${y}`);});[[6,2,4],[6,7,9],[6,11,13],[6,16,18]].forEach(([y,a,b])=>{for(let x=a;x<=b;x++)walls.add(`${x},${y}`);});const dots=new Set();for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++)if(!walls.has(`${x},${y}`))dots.add(`${x},${y}`);['1,1','19,1','1,11','19,11'].forEach(k=>dots.add(k));return{W,H,walls,dots,power:new Set(['1,1','19,1','1,11','19,11']),px:10,py:11,moveCool:0,lastDx:0,lastDy:-1,enemies:[{x:10,y:6,sx:10,sy:6,role:'hunter',px:10,py:6},{x:9,y:6,sx:9,sy:6,role:'ambush',px:9,py:6},{x:11,y:6,sx:11,sy:6,role:'pincer',px:11,py:6},{x:10,y:7,sx:10,sy:7,role:'guard',px:10,py:7}],enemyCool:.3,powered:0,target:110,collected:0,hitCooldown:0};}
function startMaze(){clearWorld();S.maze=makeMaze();P.hp=Math.max(65,P.hp);audio.setTheme(4,false,'maze');transition('DOT-MAZE RUN','COLLECT 110 DOTS. POWER CELLS SLOW BUGS — THEY STILL HURT.','maze',1.9);}
function playerBox(){return P.duck&&P.ground?{x:P.x+11,y:P.y+70,w:58,h:57}:{x:P.x+10,y:P.y+13,w:60,h:114};}
function float(t,x,y,c='#fff'){S.particles.push({kind:'text',t,x,y,c,life:1});}
function sparks(x,y,c='#6eeaff',n=12){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=rand(90,330);S.particles.push({kind:'dot',x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,c,r:rand(2,6),life:rand(.25,.7)});}}
function score(n,x=P.x,y=P.y){const v=Math.round(n*(now()<P.double?2:1)*S.mult);S.score+=v;if(!S.practice){ACH.score(S.score);ACH.profile.totals.scoreLifetime+=v;if(S.score>S.best){S.best=S.score;ACH.profile.best=S.best;}ACH.save();}float('+'+v,x,y,'#ffe66c');}
function hurt(n,knock=0){if(now()<P.inv||P.stun>0)return false;if(now()<P.shield){if(!S.practice)ACH.add('shieldBlocks',1);audio.sfx('shield');float('BLOCKED',P.x,P.y-12,'#7ef3ff');return false;}P.hp-=n;P.inv=now()+760;P.stun=.24;P.vx+=knock;P.vy=Math.min(P.vy,-95);S.shake=10;S.flash=.2;audio.sfx('hit');sparks(P.x+42,P.y+64,'#ff6075',18);if(P.hp<=0){S.lives--;if(S.lives<=0){gameOver();return true;}P.hp=100;P.x=S.stage===2?1260:210;P.vy=-350;P.inv=now()+1600;P.stun=0;}return true;}
function updatePlayer(dt,fire=true,gravity=2050){P.stun=Math.max(0,P.stun-dt);P.duck=input.down('ArrowDown','KeyS')&&P.ground&&P.stun<=0;let move=0;if(P.stun<=0)move=(input.down('ArrowLeft','KeyA')?-1:0)+(input.down('ArrowRight','KeyD')?1:0);const max=(now()<P.speed?570:450)*(P.duck?.32:1);P.vx=Q.lerp(P.vx,move*max,1-Math.pow(.001,dt));if(!move&&P.stun<=0)P.vx*=Math.pow(.02,dt);if(move)P.face=move;if(!P.duck&&P.stun<=0&&input.tap('Space','ArrowUp','KeyW')&&P.ground){P.vy=-795;P.ground=false;audio.sfx('jump');}P.vy+=gravity*dt;P.x=clamp(P.x+P.vx*dt,70,1450-P.w);P.y+=P.vy*dt;if(P.y>=Q.GROUND-P.h){P.y=Q.GROUND-P.h;P.vy=0;P.ground=true;}P.fire=Math.max(0,P.fire-dt);if(fire&&P.stun<=0&&input.tap('KeyZ','ControlLeft')&&P.fire<=0){P.fire=now()<P.double?.14:.22;const dir=P.face||1,sx=dir>0?P.x+P.w:P.x,sy=P.duck&&P.ground?P.y+103:P.y+58,vx=930*dir;S.shots.push({x:sx,y:sy,vx,vy:0,r:P.duck?7:8,owner:'p',life:2.2});if(now()<P.double)S.shots.push({x:sx,y:sy+(P.duck?8:14),vx:vx*.98,vy:0,r:6,owner:'p',life:2.2});audio.sfx('shot');}P.anim+=dt*(Math.abs(P.vx)>45?9:2.5);if(now()<P.shield){const rem=(P.shield-now())/1000;if(rem<2&&now()>S.shieldLowBeep){S.shieldLowBeep=now()+520;audio.sfx('shieldlow');}}}
function laneY(h,lane='mid'){if(lane==='ground')return Q.GROUND-h-6;if(lane==='low')return Q.GROUND-h-58;if(lane==='duck')return Q.GROUND-P.h-10;if(lane==='mid')return Q.GROUND-P.h-20;return Q.GROUND-P.h-100;}
function stageDirection(){return S.stage===2?1:-1;}function spawnX(dir,pad=80){return dir<0?Q.W+pad:-pad-120;}function schedule(delay,fn){S.pending.push({delay,fn});}function updatePending(dt){for(const p of S.pending){p.delay-=dt;if(p.delay<=0&&!p.done){p.done=true;p.fn();}}S.pending=S.pending.filter(p=>!p.done);}
function addHazard(o){const dir=o.dir??stageDirection(),gap=o.gap??1.08,release=Math.max(S.time+(o.wait??.65),S.hazardReleaseAt),wait=Math.max(0,release-S.time);S.hazardReleaseAt=release+gap;const h=o.h??90,w=o.w??100;S.entities.push({k:'haz',label:o.label,m:o.m||'slide',x:o.x??spawnX(dir),y:o.y??laneY(h,o.lane||'ground'),w,h,vx:o.vx??(o.speed??290)*dir,vy:o.vy||0,wait,life:o.life||0,damage:o.damage||24,t:0});audio.sfx('bosswarn');}
function spawnItem(lane=null,type=null){const dir=stageDirection(),t=type||pick(S.stage<3?['tape','zzap','joystick']:['disk','zzap','joystick']),ln=lane||pick(['ground','mid','high']);S.entities.push({k:'item',type:t,x:spawnX(dir,70),y:laneY(54,ln),w:54,h:54,vx:(305+S.stage*14)*dir,t:0});}
function spawnPower(lane='mid'){const dir=stageDirection();S.entities.push({k:'power',type:pick(['shield','speed','double']),x:spawnX(dir,80),y:laneY(64,lane),w:64,h:64,vx:275*dir,t:0});}
function spawnEnemy(lane='ground',speed=250,forcedDir=null,variant=null){let dir=forcedDir;if(dir==null){if(S.stage>=2){const leftBias=S.stage===2?.7:.5;dir=Math.random()<leftBias?1:-1;}else dir=stageDirection();}const low=variant==='low'||(variant==null&&lane==='ground'&&S.stage>=1&&Math.random()<.38),w=low?78:70,h=low?48:70,ln=low?'ground':lane;S.entities.push({k:'enemy',variant:low?'low':'normal',x:spawnX(dir,90),y:laneY(h,ln),w,h,vx:speed*dir,hp:1,t:Math.random()*6});}
function bedroomPattern(){const n=S.patternIndex++%7;if(n===0){addHazard({label:'LOAD ERROR',lane:'ground',w:108,h:92});schedule(1.45,()=>spawnItem('mid','tape'));}else if(n===1){addHazard({label:'LOAD ERROR — DUCK',lane:'duck',w:118,h:56,speed:300});schedule(1.45,()=>spawnEnemy('ground',270));}else if(n===2){addHazard({label:'TAPE TANGLE',lane:'ground',w:82,h:68,speed:330});schedule(1.25,()=>addHazard({label:'TAPE TANGLE',lane:'ground',w:82,h:68,speed:330,gap:.75}));schedule(2.15,()=>spawnItem('high','zzap'));}else if(n===3){spawnEnemy('mid',245);schedule(1.2,()=>spawnItem('ground','tape'));schedule(2.05,()=>addHazard({label:'LOAD ERROR — DUCK',lane:'duck',w:118,h:56,speed:295}));}else if(n===4){spawnItem('ground','tape');schedule(.55,()=>spawnItem('mid','tape'));schedule(1.1,()=>spawnItem('high','tape'));schedule(2.0,()=>addHazard({label:'LOAD ERROR',lane:'ground',w:108,h:90,speed:310}));}else if(n===5){addHazard({label:'CASSETTE CASE — DUCK',lane:'duck',w:140,h:54,speed:275});schedule(1.6,()=>spawnPower('mid'));}else{spawnEnemy('ground',300);schedule(1.15,()=>spawnEnemy('high',240));}return rand(3.3,4.3);}
function budgetPattern(){const n=S.patternIndex++%7;if(n===0){addHazard({label:'FULL PRICE £9.99',lane:'ground',w:132,h:112,speed:305});schedule(1.55,()=>spawnItem('high','tape'));}else if(n===1){addHazard({label:'£9.99 PRICE TAG — DUCK',lane:'duck',w:152,h:55,speed:320});schedule(1.55,()=>spawnItem('ground','tape'));}else if(n===2){spawnItem('ground','tape');schedule(.5,()=>spawnItem('mid','tape'));schedule(1.4,()=>addHazard({label:'£9.99!',lane:'ground',w:96,h:96,speed:345}));schedule(2.3,()=>spawnItem('high','zzap'));}else if(n===3){addHazard({label:'SHELF EDGE — JUMP',lane:'ground',w:180,h:52,speed:350});schedule(1.5,()=>addHazard({label:'PRICE CARD — DUCK',lane:'duck',w:150,h:54,speed:330}));}else if(n===4){spawnEnemy('ground',300);schedule(.8,()=>spawnEnemy('mid',260));schedule(1.8,()=>addHazard({label:'FULL PRICE',lane:'ground',w:118,h:105,speed:315}));}else if(n===5){addHazard({label:'BUDGET BIN',lane:'ground',w:210,h:66,speed:285});schedule(1.4,()=>spawnPower('high'));}else{for(let i=0;i<4;i++)schedule(i*.5,()=>spawnItem(i%2?'mid':'ground','tape'));}return rand(3.2,4.1);}
function christmasPattern(){const n=S.patternIndex++%6,dir=1;if(n===0){addHazard({label:'ROLLING PRESENT',lane:'ground',w:84,h:84,speed:285,dir});schedule(1.3,()=>spawnItem('mid'));}else if(n===1){addHazard({label:'FALLING PRESENT',m:'fall',x:rand(120,720),y:115,w:84,h:84,vx:80,vy:190,dir,gap:1.2});schedule(1.5,()=>addHazard({label:'FALLING PRESENT',m:'fall',x:rand(160,760),y:105,w:76,h:76,vx:110,vy:210,dir,gap:1.2}));}else if(n===2){addHazard({label:"GRAN'S HOUSE",lane:'ground',w:145,h:118,speed:275,dir});schedule(1.55,()=>addHazard({label:'COAT ON — DUCK',lane:'duck',w:150,h:56,speed:300,dir}));}else if(n===3){spawnEnemy('ground',265);schedule(.85,()=>spawnItem('high'));schedule(1.55,()=>spawnEnemy('mid',245));}else if(n===4){spawnItem('ground');schedule(.5,()=>spawnItem('mid'));schedule(1.0,()=>spawnItem('high'));schedule(1.9,()=>addHazard({label:'CHRISTMAS DINNER',lane:'ground',w:126,h:94,speed:315,dir}));}else{addHazard({label:'TINSEL — DUCK',lane:'duck',w:180,h:50,speed:310,dir});schedule(1.6,()=>spawnPower('mid'));}return rand(3.3,4.2);}
function amigaPattern(){const n=S.patternIndex++%6;if(n===0)addHazard({label:'BOUNCING DISK',m:'bounce',x:Q.W+80,y:Q.GROUND-88,w:88,h:88,vx:-275,vy:-190,gap:1.3});else if(n===1){addHazard({label:'READ ERROR — DUCK',lane:'duck',w:135,h:56,speed:310});schedule(1.5,()=>spawnItem('ground','disk'));}else if(n===2){addHazard({label:'DISK 1 OF 11',lane:'ground',w:92,h:78,speed:335});schedule(1.25,()=>addHazard({label:'DISK 2 OF 11',lane:'ground',w:92,h:78,speed:335,gap:.8}));schedule(2.2,()=>spawnItem('high','disk'));}else if(n===3){spawnEnemy('mid',280);schedule(1.15,()=>addHazard({label:'BOUNCING DISK',m:'bounce',x:Q.W+80,y:Q.GROUND-84,w:84,h:84,vx:-250,vy:-175,gap:1.3}));}else if(n===4){spawnItem('ground','disk');schedule(.65,()=>spawnItem('mid','disk'));schedule(1.35,()=>spawnPower('high'));}else{addHazard({label:'WORKBENCH WINDOW — DUCK',lane:'duck',w:170,h:56,speed:300});schedule(1.6,()=>spawnEnemy('ground',295));}return rand(3.1,4.0);}
function guruBeam(finalBoss=false){const targetX=clamp(P.x+P.w/2-43+rand(-65,65),100,1420);addHazard({label:'GURU GLITCH — MOVE',m:'beam',x:targetX,y:420,w:86,h:315,vx:0,wait:finalBoss?3:2,life:1.3,damage:finalBoss?30:42,gap:finalBoss?1.5:1.3});}
function guruPattern(){const n=S.patternIndex++%6;if(n===0)guruBeam(false);else if(n===1){addHazard({label:'CORRUPT BLOCK',lane:'ground',w:104,h:96,speed:285});schedule(1.55,()=>guruBeam(false));}else if(n===2){spawnEnemy('mid',285);schedule(.95,()=>spawnEnemy('ground',320));schedule(1.75,()=>guruBeam(false));}else if(n===3){spawnItem('mid','disk');schedule(.75,()=>spawnItem('high','zzap'));schedule(1.65,()=>guruBeam(false));}else if(n===4){addHazard({label:'GURU BOX — JUMP',lane:'ground',w:118,h:112,speed:305,gap:1.25});schedule(1.55,()=>addHazard({label:'GURU BOX — JUMP',lane:'ground',w:92,h:88,speed:330,dir:1,gap:1.25}));}else{addHazard({label:'MEMORY BOX',lane:'ground',w:96,h:82,speed:330,dir:Math.random()<.5?-1:1,gap:1.3});schedule(1.5,()=>spawnEnemy('mid',310));schedule(2.35,()=>guruBeam(false));}return rand(4.0,5.0);}
function stagePattern(){return(S.stage===0?bedroomPattern:S.stage===1?budgetPattern:S.stage===2?christmasPattern:S.stage===3?amigaPattern:guruPattern)();}
function updateStage(dt){S.elapsed+=dt;S.stageGrace=Math.max(0,S.stageGrace-dt);updatePlayer(dt,true);updatePending(dt);S.patternTimer-=dt;S.itemSpawn-=dt;S.powerSpawn-=dt;S.enemySpawn-=dt;if(S.stageGrace<=0&&S.patternTimer<=0)S.patternTimer=stagePattern();if(S.itemSpawn<=0){spawnItem();S.itemSpawn=rand(5.2,7.1);}if(S.powerSpawn<=0){spawnPower(pick(['mid','high']));S.powerSpawn=rand(10,14);}if(S.stageGrace<=0&&S.enemySpawn<=0){const low=Math.random()<(.26+S.stage*.05),lane=low?'ground':pick(['ground','mid']);spawnEnemy(lane,265+S.stage*20,null,low?'low':null);S.enemySpawn=rand(Math.max(2.7,5.2-S.stage*.5),Math.max(3.7,6.1-S.stage*.42));}updateEntities(dt);updateShots(dt);if(S.elapsed>=Q.STAGES[S.stage].duration)enterBoss();}
function updateEntities(dt){const pb=playerBox();for(const e of S.entities){e.t=(e.t||0)+dt;if(e.wait>0){e.wait-=dt;continue;}if(e.k==='haz'){if(e.m==='fall'){e.vy+=650*dt;e.y+=e.vy*dt;if(e.y>Q.GROUND-e.h){e.y=Q.GROUND-e.h;e.vy=0;if(Math.abs(e.vx)<120)e.vx=S.stage===2?250:-250;}}else if(e.m==='bounce'){e.vy+=760*dt;e.y+=e.vy*dt;if(e.y>Q.GROUND-e.h){e.y=Q.GROUND-e.h;e.vy=-190;}}else if(e.m==='beam'){e.life-=dt;if(e.life<=0)e.dead=true;}e.x+=(e.vx||0)*dt;}else{e.x+=(e.vx||0)*dt;if(e.k==='enemy'){if(S.stage===3)e.y+=Math.sin(e.t*5)*2.1;else if(S.stage===4)e.y+=Math.sin(e.t*7)*3.2;}}const box={x:e.x,y:e.y,w:e.w,h:e.h};if(!e.dead&&!(e.m==='beam'&&e.hitPlayer)&&rhit(pb,box)){if(e.k==='item'){score(130,e.x,e.y);audio.sfx('pickup');if(!S.practice){ACH.add('pickups',1);if(e.type==='tape')ACH.add('tapes',1);}e.dead=true;}else if(e.k==='power'){if(e.type==='shield')P.shield=now()+7600;if(e.type==='speed')P.speed=now()+7200;if(e.type==='double')P.double=now()+7200;audio.sfx('pickup');score(200,e.x,e.y);e.dead=true;}else{hurt(e.damage||(e.k==='enemy'?18:24),e.x>P.x?-250:250);if(e.m==='beam')e.hitPlayer=true;else e.dead=true;}}if(e.x<-260||e.x>Q.W+260)e.dead=true;}S.entities=S.entities.filter(e=>!e.dead);}
const BOSS_PROFILE=[{speed:285,warn:1.4,min:3.45,max:4.1,opts:['direct','high','low']},{speed:315,warn:1.22,min:2.95,max:3.6,opts:['lead','high','low','bracket']},{speed:345,warn:1.05,min:2.55,max:3.2,opts:['lead','high','low','sweep','bracket']},{speed:375,warn:.9,min:2.2,max:2.9,opts:['curve','lead','high','low','bracket','sweep']},{speed:341,warn:1.55,min:2.8,max:4.0,opts:['curve','high','low','fan','sweep']}];
function enterBoss(){S.entities=S.entities.filter(e=>e.k==='item'||e.k==='power');S.pending=[];const st=Q.STAGES[S.stage],left=S.stage===2;S.boss={x:left?250:1320,y:535,homeX:left?280:1320,homeY:535,w:205,h:180,hp:st.bossHp,max:st.bossHp,t:0,next:1.55,warn:0,warnDur:BOSS_PROFILE[S.stage].warn,type:'direct',label:'TRACKING SHOT',relocate:2.5,volley:[],dir:S.stage===4?-1:1,hazardTimer:4.2};audio.setTheme(st.music,true,st.id);transition(`BOSS: ${st.boss}`,'READ THE ATTACK. MOVE, JUMP OR DUCK.','boss',1.5);}
function bossAttack(){const b=S.boss,p=BOSS_PROFILE[S.stage];b.type=pick(p.opts);b.label={direct:'TRACKING SHOT — MOVE',lead:'LEADING SHOT — CHANGE DIRECTION',high:'HIGH SHOT — DUCK',low:'LOW SHOT — JUMP',bracket:'TWO-SHOT BRACKET — FIND THE GAP',sweep:'SWEEP VOLLEY — KEEP MOVING',curve:'CURVE SHOT — KEEP MOVING',fan:'THREE-WAY FAN — USE THE GAP'}[b.type];b.warnDur=p.warn;b.warn=p.warn;b.volley=[];audio.sfx('bosswarn');}
function queueBossShot(delay,kind,off=0,laneOffset=0){S.boss.volley.push({delay,kind,off,laneOffset});}
function buildBossVolley(){const b=S.boss;if(b.type==='bracket'){queueBossShot(0,'high',-35);queueBossShot(.68,'low',35);}else if(b.type==='sweep'){queueBossShot(0,'fixed',-35,-105);queueBossShot(.62,'fixed',0,35);}else if(b.type==='fan'){queueBossShot(0,'fixed',-42,-75);queueBossShot(.58,'fixed',0,0);queueBossShot(1.16,'fixed',42,75);}else queueBossShot(0,b.type,0);}
function bossShoot(kind,off=0,laneOffset=0){const b=S.boss,p=BOSS_PROFILE[S.stage],sx=b.x+(b.x>P.x?-b.w/2:b.w/2),sy=b.y+off;let tx=P.x+P.w/2,ty=P.y+62;if(kind==='lead')tx+=P.vx*.34;if(kind==='high')ty=Q.GROUND-P.h+50;if(kind==='low')ty=Q.GROUND-22;if(kind==='fixed'){tx=P.x+(b.x>P.x?-280:280);ty=P.y+62+laneOffset;}const dx=tx-sx,dy=ty-sy,m=Math.max(1,Math.hypot(dx,dy));S.shots.push({x:sx,y:sy,vx:dx/m*p.speed,vy:dy/m*p.speed,r:S.stage===4?15:17,owner:'b',life:7,curve:kind==='curve'?(P.x<b.x?95:-95):0});audio.sfx('shot');}
function moveBoss(dt){const b=S.boss,i=S.stage;b.t+=dt;b.relocate-=dt;if(i===0){b.x=b.homeX+Math.sin(b.t*.8)*72;b.y=540+Math.sin(b.t*1.5)*40;}else if(i===1){b.x=b.homeX+Math.sin(b.t*1.05)*180;b.y=b.homeY+Math.sin(b.t*2.1)*58;if(b.relocate<=0){b.homeY=pick([500,535,565]);b.relocate=rand(2.2,3.4);}}else if(i===2){b.x=320+Math.sin(b.t*.82)*205;b.y=520+Math.sin(b.t*2.0)*90;}else if(i===3){b.x=1260+Math.sin(b.t*1.35)*220;b.y=515+Math.sin(b.t*2.55)*82;}else{b.x+=b.dir*250*dt;if(b.x<230){b.x=230;b.dir=1;}else if(b.x>1370){b.x=1370;b.dir=-1;}b.y=500+Math.sin(b.t*2.15)*80;}}
function updateBoss(dt){const b=S.boss;if(!b)return;updatePlayer(dt,true);updateEntities(dt);updateShots(dt);moveBoss(dt);b.next-=dt;b.hazardTimer-=dt;if(b.warn>0){b.warn-=dt;if(b.warn<=0)buildBossVolley();}else if(!b.volley.length&&b.next<=0){bossAttack();const p=BOSS_PROFILE[S.stage];b.next=rand(p.min,p.max);}if(b.volley.length){for(const sh of b.volley)sh.delay-=dt;for(const sh of b.volley.filter(x=>x.delay<=0&&!x.done)){sh.done=true;bossShoot(sh.kind,sh.off,sh.laneOffset);}b.volley=b.volley.filter(x=>!x.done);}if(S.stage===4&&b.hazardTimer<=0){if(Math.random()<.58)guruBeam(true);else addHazard({label:'CORRUPT BLOCK',lane:'ground',w:98,h:90,speed:250,wait:1.2});b.hazardTimer=rand(4.2,5.8);}if(b.hp<=0){if(!S.practice){ACH.add('bosses',1);if(S.stage===1)ACH.flag('budgetBoss');if(S.stage===2)ACH.flag('xmasBoss');}score(1800+S.stage*400,b.x,b.y);afterBoss();}}
function updateShots(dt){for(const s of S.shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.vy+=(s.curve||0)*dt;s.life-=dt;if(s.owner==='p'){if(S.boss&&rhit({x:s.x-s.r,y:s.y-s.r,w:s.r*2,h:s.r*2},{x:S.boss.x-S.boss.w/2,y:S.boss.y-S.boss.h/2,w:S.boss.w,h:S.boss.h})){S.boss.hp-=1;s.dead=true;sparks(s.x,s.y,'#ffe66c',7);}for(const e of S.entities)if(!s.dead&&e.k==='enemy'&&rhit({x:s.x-s.r,y:s.y-s.r,w:s.r*2,h:s.r*2},e)){e.dead=true;s.dead=true;score(180,e.x,e.y);if(!S.practice)ACH.add('kills',1);}}else if(rhit({x:s.x-s.r,y:s.y-s.r,w:s.r*2,h:s.r*2},playerBox())){hurt(18,s.vx>0?170:-170);s.dead=true;}if(s.life<=0||s.x<-100||s.x>1700||s.y<-100||s.y>1000)s.dead=true;}S.shots=S.shots.filter(s=>!s.dead);S.entities=S.entities.filter(e=>!e.dead);}
function updateBeads(dt){S.beadTime+=dt;updatePlayer(dt,true,2350);S.patternTimer-=dt;S.beadEnemyTimer-=dt;if(S.patternTimer<=0){const speed=rand(360,455),leftMarks=[5.5,10.5,15.5,20.5,24.5],fromLeft=S.beadLeftShots<leftMarks.length&&S.beadTime>leftMarks[S.beadLeftShots],dir=fromLeft?1:-1,x=fromLeft?-52:Q.W+52;if(fromLeft)S.beadLeftShots++;S.entities.push({k:'bead',x,y:Q.GROUND-44,w:44,h:44,vx:speed*dir,t:0});if(S.beadTime>11&&Math.random()<.34)schedule(.72,()=>S.entities.push({k:'bead',x:dir<0?Q.W+52:-52,y:Q.GROUND-44,w:44,h:44,vx:speed*dir*.95,t:0}));S.patternTimer=rand(.9,1.32);}if(S.beadEnemyTimer<=0){const dir=Math.random()<.28?1:-1,low=Math.random()<.5;spawnEnemy(low?'ground':'mid',rand(245,325),dir,low?'low':'normal');S.beadEnemyTimer=rand(3.6,5.0);}updatePending(dt);const pb=playerBox();for(const e of S.entities){if(e.k==='bead'){e.x+=e.vx*dt;e.t+=dt;if(!e.hit&&rhit(pb,e)){hurt(22,e.vx>0?180:-180);e.hit=true;}const passed=e.vx<0?e.x+e.w<P.x:e.x>P.x+P.w;if(!e.scored&&passed&&P.y<Q.GROUND-P.h-12){e.scored=true;score(120,e.x,e.y);if(!S.practice)ACH.add('cleanJumps',1);}if(e.x<-90||e.x>Q.W+90)e.dead=true;}else if(e.k==='enemy'){e.x+=e.vx*dt;e.t+=dt;if(!e.dead&&rhit(pb,e)){hurt(e.variant==='low'?16:19,e.x>P.x?-220:220);e.dead=true;}if(e.x<-220||e.x>Q.W+220)e.dead=true;}}updateShots(dt);S.entities=S.entities.filter(e=>!e.dead);if(S.beadTime>28){if(!S.practice&&P.hp>=100)ACH.flag('beadPerfect');if(S.practice)transition('PRACTICE COMPLETE','Electric Bead Run complete.','title',1.8);else enterStage(1);}}
function fighterPlayerAttack(type){if(P.attack||P.duck||P.stun>0)return;P.attack=type;P.attackT=now();P.attackLen=type==='kick'?500:340;P.hitLatch=false;audio.sfx(type);}
function enemyStart(type){const f=S.fighter;if(!f||f.attack||f.stun>0)return;f.attack=type;f.attackT=now();f.attackLen=type==='kick'?540:370;f.hitLatch=false;f.vx=f.face*155;f.message=type==='punch'?'TIER-TEX: HIGH PUNCH — DUCK':'TIER-TEX: LOW KICK — JUMP';f.messageT=1.1;}
function fighterHit(target,damage,knock,label){if(target===P){if(hurt(damage,knock))float(label,P.x,P.y-18,'#ffcf68');return;}target.hp-=damage;target.stun=.34;target.vx=knock;target.attack=null;target.guard=0;audio.sfx('hit');sparks(target.x,target.y+65,'#ffcf68',14);float(label,target.x,target.y-16,'#ffe66c');}
function fighterBodyBox(a,isPlayer=false){if(isPlayer){if(P.duck&&P.ground)return{x:P.x+10,y:P.y+73,w:60,h:54};return{x:P.x+10,y:P.y+16,w:60,h:109};}return{x:a.x-38,y:a.y+10,w:76,h:142};}
function fighterAttackBox(a,type,prog,face,isPlayer=false){const active=type==='kick'?(prog>.30&&prog<.68):(prog>.26&&prog<.65);if(!active)return null;const swing=Math.sin(prog*Math.PI),baseX=isPlayer?(face>0?a.x+a.w-4:a.x+4):(a.x+face*24);if(type==='punch'){const reach=(isPlayer?126:134)*(.72+.28*swing),y=isPlayer?a.y+38:a.y+39;return face>0?{x:baseX,y,w:reach,h:38}:{x:baseX-reach,y,w:reach,h:38};}const reach=(isPlayer?154:164)*(.72+.28*swing),y=isPlayer?a.y+86:a.y+93;return face>0?{x:baseX,y,w:reach,h:46}:{x:baseX-reach,y,w:reach,h:46};}
function chooseFighterAI(f,dist,ad){const toward=-Math.sign(dist||1),away=-toward,r=Math.random();if(P.attack&&ad<225){if(r<.33){f.guard=.44;f.ai='guard';}else if(r<.58){f.vx=away*rand(200,285);f.ai='backstep';}else if(r<.78&&f.ground){f.vy=-645;f.ground=false;f.vx=toward*185;f.ai='jump-read';}else if(f.cool<=0){enemyStart(Math.random()<.5?'punch':'kick');f.cool=rand(.34,.62);f.ai='counter';}return;}if(ad>330){if(r<.31){f.vx=toward*rand(190,285);f.ai='advance';}else if(r<.58&&f.ground){f.vy=-650;f.ground=false;f.vx=toward*rand(190,260);f.ai='jump-in';}else if(r<.75){f.vx=away*rand(90,150);f.ai='feint';}else{f.vx=toward*rand(120,185);f.ai='stalk';}}else if(ad>180){if(f.cool<=0&&r<.72){f.vx=toward*175;enemyStart(r<.36?'kick':'punch');f.cool=rand(.38,.7);f.ai='attack';}else if(r<.82){f.vx=away*rand(120,195);f.ai='circle-out';}else if(r<.93&&f.ground){f.vy=-610;f.ground=false;f.vx=(Math.random()<.65?toward:away)*165;f.ai='hop';}else{f.vx=toward*rand(110,180);f.ai='probe';}}else{if(f.cool<=0&&r<.88){enemyStart(r<.46?'kick':'punch');f.cool=rand(.32,.62);f.ai='pressure';}else if(r<.94){f.vx=away*rand(150,230);f.ai='reset';}else{f.guard=.35;f.ai='guard';}}}
function updateFighter(dt){const f=S.fighter;if(!f)return;f.boutTime=Math.max(0,f.boutTime-dt);P.stun=Math.max(0,P.stun-dt);f.stun=Math.max(0,f.stun-dt);f.messageT=Math.max(0,f.messageT-dt);f.guard=Math.max(0,f.guard-dt);f.cool-=dt;f.think-=dt;P.duck=input.down('ArrowDown','KeyS')&&P.ground&&P.stun<=0;let mv=0;if(P.stun<=0)mv=(input.down('ArrowLeft','KeyA')?-1:0)+(input.down('ArrowRight','KeyD')?1:0);P.vx=Q.lerp(P.vx,mv*(P.duck?130:340),1-Math.pow(.001,dt));if(!mv&&P.stun<=0)P.vx*=Math.pow(.02,dt);if(input.tap('Space','ArrowUp','KeyW')&&P.ground&&!P.duck&&P.stun<=0){P.vy=-760;P.ground=false;audio.sfx('jump');}if(P.stun<=0&&input.tap('KeyZ','ControlLeft'))fighterPlayerAttack('punch');if(P.stun<=0&&input.tap('KeyX','KeyC'))fighterPlayerAttack('kick');P.vy+=2050*dt;P.x=clamp(P.x+P.vx*dt,90,1430);P.y+=P.vy*dt;if(P.y>=Q.GROUND-P.h){P.y=Q.GROUND-P.h;P.vy=0;P.ground=true;}f.face=P.x<f.x?-1:1;P.face=f.x>=P.x?1:-1;const dist=f.x-P.x,ad=Math.abs(dist);if(f.stun<=0&&f.think<=0&&!f.attack){f.think=rand(.12,.27);chooseFighterAI(f,dist,ad);}if(f.guard>0)f.vx*=.8;f.vy+=2050*dt;f.x=clamp(f.x+f.vx*dt,100,1500);f.y+=f.vy*dt;if(f.y>=Q.GROUND-f.h){f.y=Q.GROUND-f.h;f.vy=0;f.ground=true;}f.vx*=Math.pow(f.stun>0?.28:.16,dt);if(P.attack){const prog=clamp((now()-P.attackT)/P.attackLen,0,1),atk=fighterAttackBox(P,P.attack,prog,P.face,true),body=fighterBodyBox(f,false);if(atk&&rhit(atk,body)&&!P.hitLatch){P.hitLatch=true;let dmg=P.attack==='kick'?14:9;if(f.guard>0){dmg=Math.ceil(dmg*.35);f.hp-=dmg;f.vx=P.face*120;float('BLOCKED',f.x,f.y-15,'#8feaff');}else{fighterHit(f,dmg,P.face*(P.attack==='kick'?390:300),P.attack==='kick'?'KICK':'PUNCH');P.combo=now()<P.comboUntil?P.combo+1:1;P.comboUntil=now()+900;if(!S.practice&&P.combo>=5)ACH.flag('fighterCombo');score(90+P.combo*10,f.x,f.y);}}if(prog>=1){P.attack=null;P.hitLatch=false;}}if(f.attack){const prog=clamp((now()-f.attackT)/f.attackLen,0,1),atk=fighterAttackBox(f,f.attack,prog,f.face,false),body=fighterBodyBox(P,true);if(atk&&rhit(atk,body)&&!f.hitLatch){f.hitLatch=true;fighterHit(P,f.attack==='kick'?18:13,f.face*330,f.attack==='kick'?'STAGGERED':'HIT');}if(prog>=1){f.attack=null;f.hitLatch=false;f.cool=rand(.32,.62);}}if(Math.abs(f.x-P.x)<72&&P.ground&&f.ground){const push=(72-Math.abs(f.x-P.x))*.5;if(f.x>P.x){f.x+=push;P.x-=push;}else{f.x-=push;P.x+=push;}}if(f.hp<=0){if(!S.practice)ACH.add('fighterWins',1);score(2600,f.x,f.y);if(S.practice)transition('PRACTICE COMPLETE','Tier-Tex has been defeated.','title',1.8);else startInvaders();return;}if(f.boutTime<=0){if(f.hp<P.hp)score(1300,f.x,f.y);if(S.practice)transition('BOUT COMPLETE','Timer called it.','title',1.8);else startInvaders();}}
function updateInvaders(dt){const g=S.inv;if(!g)return;g.elapsed+=dt;g.invuln=Math.max(0,g.invuln-dt);const move=(input.down('ArrowLeft','KeyA')?-1:0)+(input.down('ArrowRight','KeyD')?1:0);g.shipX=clamp(g.shipX+move*535*dt,75,1525);g.fire-=dt;if(input.tap('KeyZ','ControlLeft')&&g.fire<=0){g.fire=.34;g.shots.push({x:g.shipX,y:770,vx:0,vy:-790,owner:'p'});audio.sfx('shot');}const alive=g.aliens.filter(a=>a.alive),ratio=1-alive.length/g.aliens.length,spd=g.speed+ratio*145;let edge=false;for(const a of alive){a.phase+=dt*6;a.x+=g.dir*spd*dt;if(a.x<70||a.x+a.w>1530)edge=true;}if(edge){g.dir*=-1;for(const a of alive){a.x+=g.dir*spd*dt;a.y+=28;}}g.enemyCool-=dt;if(g.enemyCool<=0&&alive.length){const front=alive.slice().sort((a,b)=>Math.abs((a.x+a.w/2)-g.shipX)-Math.abs((b.x+b.w/2)-g.shipX)),count=ratio>.5?3:ratio>.12?2:1;for(let i=0;i<count;i++){const shooter=i===0&&Math.random()<.58?front[0]:pick(alive),sx=shooter.x+shooter.w/2,vy=270+ratio*125,vx=0;g.shots.push({x:sx,y:shooter.y+shooter.h,vx,vy,owner:'e'});}g.enemyCool=rand(Math.max(.22,.54-ratio*.18),Math.max(.38,.76-ratio*.16));}for(const sh of g.shots){sh.x+=(sh.vx||0)*dt;sh.y+=sh.vy*dt;let bunkerHit=false;for(const b of g.bunkers||[]){if(b.hp>0&&sh.x>b.x-b.w/2&&sh.x<b.x+b.w/2&&sh.y>b.y&&sh.y<b.y+b.h){b.hp--;sh.dead=true;bunkerHit=true;sparks(sh.x,sh.y,'#7df0a5',6);break;}}if(bunkerHit)continue;if(sh.owner==='p'){for(const a of alive)if(a.alive&&sh.x>a.x&&sh.x<a.x+a.w&&sh.y>a.y&&sh.y<a.y+a.h){a.alive=false;sh.dead=true;score(130+a.row*10,a.x,a.y);sparks(a.x+a.w/2,a.y,'#78efff',10);break;}}else if(g.invuln<=0&&sh.x>g.shipX-48&&sh.x<g.shipX+48&&sh.y>765&&sh.y<835){sh.dead=true;g.shield--;g.invuln=1;S.shake=9;audio.sfx('hit');if(g.shield<=0){S.lives--;if(S.lives<=0){gameOver();return;}g.shield=3;}}if(sh.y<85||sh.y>870||sh.x<0||sh.x>Q.W)sh.dead=true;}g.shots=g.shots.filter(s=>!s.dead);if(alive.some(a=>a.y>690)){S.lives--;if(S.lives<=0){gameOver();return;}startInvaders();return;}if(g.aliens.every(a=>!a.alive)){if(!S.practice)ACH.flag('alienFormation');score(3000,800,300);if(S.practice)transition('PRACTICE COMPLETE','Alien formation cleared.','title',1.8);else enterStage(2);}}
function mazeCan(m,x,y){return x>=0&&y>=0&&x<m.W&&y<m.H&&!m.walls.has(`${x},${y}`);}function mazeCollect(m){const k=`${m.px},${m.py}`;if(m.dots.has(k)){m.dots.delete(k);m.collected++;score(m.power.has(k)?150:40,800,450);if(m.power.has(k)){m.powered=4.2;m.power.delete(k);audio.sfx('shield');}}}
function mazeDistance(m,sx,sy,tx,ty){if(sx===tx&&sy===ty)return 0;const q=[[sx,sy,0]],seen=new Set([`${sx},${sy}`]);for(let i=0;i<q.length;i++){const[x,y,d]=q[i];for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=`${nx},${ny}`;if(!mazeCan(m,nx,ny)||seen.has(k))continue;if(nx===tx&&ny===ty)return d+1;seen.add(k);q.push([nx,ny,d+1]);}}return 999;}
function mazeTarget(m,e){let tx=m.px,ty=m.py;if(e.role==='ambush'){tx=clamp(m.px+m.lastDx*4,1,m.W-2);ty=clamp(m.py+m.lastDy*4,1,m.H-2);if(!mazeCan(m,tx,ty)){tx=m.px;ty=m.py;}}else if(e.role==='pincer'){tx=clamp(m.px-m.lastDx*3,1,m.W-2);ty=clamp(m.py-m.lastDy*3,1,m.H-2);if(!mazeCan(m,tx,ty)){tx=m.px;ty=m.py;}}else if(e.role==='guard'&&m.power.size){let best=null,bd=999;for(const k of m.power){const[x,y]=k.split(',').map(Number),d=mazeDistance(m,m.px,m.py,x,y);if(d<bd){bd=d;best=[x,y];}}if(best){tx=best[0];ty=best[1];}}return[tx,ty];}
function updateMaze(dt){const m=S.maze;if(!m)return;m.moveCool-=dt;m.enemyCool-=dt;m.powered=Math.max(0,m.powered-dt);m.hitCooldown=Math.max(0,m.hitCooldown-dt);let dx=0,dy=0;if(input.down('ArrowLeft','KeyA'))dx=-1;else if(input.down('ArrowRight','KeyD'))dx=1;else if(input.down('ArrowUp','KeyW'))dy=-1;else if(input.down('ArrowDown','KeyS'))dy=1;if(m.moveCool<=0&&(dx||dy)){if(mazeCan(m,m.px+dx,m.py+dy)){m.px+=dx;m.py+=dy;m.lastDx=dx;m.lastDy=dy;mazeCollect(m);}m.moveCool=.095;}if(m.enemyCool<=0){const base=m.collected>80?.13:m.collected>45?.15:.18;m.enemyCool=m.powered>0?.27:base;for(const e of m.enemies){const [tx,ty]=mazeTarget(m,e),opts=[[1,0],[-1,0],[0,1],[0,-1]].map(([x,y])=>({x:e.x+x,y:e.y+y})).filter(p=>mazeCan(m,p.x,p.y)),nonReverse=opts.filter(p=>!(p.x===e.px&&p.y===e.py)),pool=nonReverse.length?nonReverse:opts;pool.sort((a,b)=>{const da=mazeDistance(m,a.x,a.y,tx,ty),db=mazeDistance(m,b.x,b.y,tx,ty),pa=mazeDistance(m,a.x,a.y,m.px,m.py),pb=mazeDistance(m,b.x,b.y,m.px,m.py);return m.powered>0?(pb-pa):(da-db);});let choice=pool[0];if(Math.random()<.12&&pool.length>1)choice=pool[1];if(choice){e.px=e.x;e.py=e.y;e.x=choice.x;e.y=choice.y;}if(e.x===m.px&&e.y===m.py&&m.hitCooldown<=0){const powered=m.powered>0,damage=powered?12:30;P.hp-=damage;m.hitCooldown=.75;S.flash=.22;audio.sfx('hit');float(powered?'POWER COLLISION -12':'BUG HIT -30',800,430,powered?'#ffe56e':'#ff6174');if(powered){m.powered=Math.max(0,m.powered-1.6);score(120,800,450);}e.x=e.sx;e.y=e.sy;e.px=e.sx;e.py=e.sy;if(P.hp<=0){S.lives--;if(S.lives<=0){gameOver();return;}P.hp=100;m.px=10;m.py=11;m.hitCooldown=1.2;}}}}if(m.collected>=m.target){if(!S.practice)ACH.flag('mazeClear');score(2800,800,450);if(S.practice)transition('PRACTICE COMPLETE','Dot-Maze cleared.','title',1.8);else enterStage(3);}}
function update(dt){S.time+=dt;if(S.mode==='transition'){S.transition.t+=dt;if(S.transition.t>=S.transition.dur)mode(S.transition.next);}else if(S.mode==='stage')updateStage(dt);else if(S.mode==='boss')updateBoss(dt);else if(S.mode==='beads')updateBeads(dt);else if(S.mode==='fighter')updateFighter(dt);else if(S.mode==='invaders')updateInvaders(dt);else if(S.mode==='maze')updateMaze(dt);for(const p of S.particles){p.life-=dt;if(p.kind==='dot'){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=360*dt;}else p.y-=34*dt;}S.particles=S.particles.filter(p=>p.life>0);S.flash=Math.max(0,S.flash-dt);S.shake*=Math.pow(.01,dt);}
function drawLayer(id,suffix){const im=assets.get('layer_'+id+suffix);if(im)ctx.drawImage(im,0,0,Q.W,Q.H);}
function foreground(id){drawLayer(id,'Front');}
function bg(id){const im=assets.get('custom_bg_'+id)||assets.get('bg_'+id);if(im)ctx.drawImage(im,0,0,Q.W,Q.H);else{const pal={bedroom:['#19133a','#39284c'],budget:['#101b2d','#4c2d25'],christmas:['#162e32','#402044'],amiga:['#06192c','#192868'],guru:['#13020b','#460811'],beads:['#341d65','#111128'],fighter:['#8072b7','#302b5a'],invaders:['#02040f','#08102a'],maze:['#08010f','#15072c']}[id]||['#111','#222'],g=ctx.createLinearGradient(0,0,0,Q.H);g.addColorStop(0,pal[0]);g.addColorStop(1,pal[1]);ctx.fillStyle=g;ctx.fillRect(0,0,Q.W,Q.H);}drawLayer(id,'Back');drawLayer(id,'Mid');}
function drawLine(x1,y1,x2,y2,w,c){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();}
function drawHead(cx,top,size,face=1){const avatar=assets.get('player_avatar'),custom=assets.get('player_head'),source=custom||assets.get('player_mascot')||assets.get('mascot_source');ctx.save();if(face<0){ctx.translate(cx*2,0);ctx.scale(-1,1);}if(avatar){ctx.save();ctx.beginPath();ctx.arc(cx,top+size*.5,size*.48,0,Math.PI*2);ctx.clip();const sw=avatar.naturalWidth,sh=avatar.naturalHeight,s=Math.min(sw,sh),sx=(sw-s)/2,sy=(sh-s)/2;ctx.drawImage(avatar,sx,sy,s,s,cx-size*.5,top,size,size);ctx.restore();ctx.strokeStyle='#72eaff';ctx.lineWidth=4;ctx.beginPath();ctx.arc(cx,top+size*.5,size*.48,0,Math.PI*2);ctx.stroke();}else if(custom)ctx.drawImage(source,cx-size*.5,top,size,size);else if(source){const sw=source.naturalWidth*.49,sh=source.naturalHeight*.74;ctx.drawImage(source,0,0,sw,sh,cx-size*.55,top,size*1.1,size*1.05);}else{ctx.fillStyle='#efb58e';ctx.beginPath();ctx.arc(cx,top+size*.5,size*.45,0,Math.PI*2);ctx.fill();}ctx.restore();}
function playerSpriteState(){if(P.stun>0)return'hit';if(P.attack)return P.attack;if(P.duck&&P.ground)return P.fire>0?'duckFire':'duck';if(!P.ground)return P.vy<0?'jump':'fall';if(P.fire>0)return'fire';if(Math.abs(P.vx)>38)return'run';return'idle';}
function drawPlayerSheet(){const im=assets.get('sheet_player'),meta=Q.customAssetMeta?.('spritesheets','player');if(!im||!meta||typeof Q.drawSpriteSheet!=='function')return false;const w=Number(meta.drawWidth)||150,h=Number(meta.drawHeight)||190,cx=P.x+P.w/2,x=cx-w/2,y=Q.GROUND-h,face=P.face||1;if(!Q.drawSpriteSheet(ctx,im,meta,playerSpriteState(),S.time,x,y,w,h,face))return false;if(meta.avatarHead!==false){const headSize=Number(meta.headSize)||Math.min(92,h*.42),headTop=y+(Number(meta.headOffsetY)||0);drawHead(cx,headTop,headSize,face);}bar(P.x-14,P.y-34,108,P.hp/P.max,'#62ed8e');if(now()<P.shield){const rem=clamp((P.shield-now())/7600,0,1);ctx.strokeStyle=rem<.25?'#ffd45d':'#70efff';ctx.lineWidth=5;ctx.beginPath();ctx.arc(cx,P.y+62,78,-Math.PI/2,-Math.PI/2+Math.PI*2*rem);ctx.stroke();}return true;}
function drawPlayer(){if(drawPlayerSheet())return;const duck=P.duck&&P.ground,run=Math.abs(P.vx)>38&&!duck&&P.stun<=0,jump=!P.ground,ap=P.attack?clamp((now()-P.attackT)/P.attackLen,0,1):0,punch=P.attack==='punch'?Math.sin(ap*Math.PI):0,kick=P.attack==='kick'?Math.sin(ap*Math.PI):0,walk=run?Math.sin(P.anim):0,cx=P.x+P.w/2,gy=P.y+P.h,bodyTop=duck?gy-88:gy-120,hip=duck?gy-48:gy-61,shoulder=bodyTop+38,headTop=duck?bodyTop-35:bodyTop-54,face=P.face||1;if(now()<P.inv&&Math.floor(now()/85)%2===0)ctx.globalAlpha=.45;ctx.save();ctx.fillStyle='rgba(0,0,0,.32)';ctx.beginPath();ctx.ellipse(cx,gy+10,duck?45:39,10,0,0,Math.PI*2);ctx.fill();const body=assets.get('player_body'),arm=assets.get('player_arm'),leg=assets.get('player_leg'),ls=jump?0:walk*18;for(const ld of[{x:cx-15,s:ls,front:false},{x:cx+15,s:-ls,front:true}]){const tx=ld.x+ld.s*.55+(P.attack==='kick'&&ld.front?face*62*kick:0),ty=hip+(duck?24:31)-(P.attack==='kick'&&ld.front?26*kick:0),fx=tx+ld.s*.55+(P.attack==='kick'&&ld.front?face*72*kick:0),fy=jump?gy-18:(P.attack==='kick'&&ld.front?gy-45*kick:gy-4);if(leg){const lh=Math.max(58,fy-hip+25);ctx.save();ctx.translate(ld.x,hip);ctx.rotate(Math.atan2(fy-hip,fx-ld.x)-Math.PI/2);ctx.drawImage(leg,-19,0,38,lh);ctx.restore();}else{drawLine(ld.x,hip,tx,ty,31,'#07111b');drawLine(ld.x,hip,tx,ty,21,'#194b67');drawLine(tx,ty,fx,fy-8,29,'#07111b');drawLine(tx,ty,fx,fy-8,19,'#24617e');ctx.fillStyle='#080b10';rr(fx-(face>0?15:27),fy-15,42,20,8);}}if(body)ctx.drawImage(body,cx-49,bodyTop+20,98,duck?72:92);else{ctx.fillStyle='#194b67';ctx.strokeStyle='#07111b';ctx.lineWidth=7;rr(cx-45,bodyTop+22,90,88,22,true,true);ctx.fillStyle='#2e7898';rr(cx-31,bodyTop+54,62,18,8);text('CCG',cx,bodyTop+68,13,'#fff','center',900);}const as=jump?0:-walk*20,fsx=cx+face*34,bsx=cx-face*34,fhx=P.attack==='punch'?fsx+face*(50+70*punch):(P.attack==='kick'?cx+face*22:fsx+face*22+as*.4),fhy=P.attack==='punch'?shoulder+8:shoulder+44+as*.35,bhx=bsx-face*18-as*.4,bhy=shoulder+46-as*.35;function limb(sx,sy,hx,hy,front){if(arm){const dx=hx-sx,dy=hy-sy,len=Math.max(42,Math.hypot(dx,dy));ctx.save();ctx.translate(sx,sy);ctx.rotate(Math.atan2(dy,dx));if(!front)ctx.scale(1,-1);ctx.drawImage(arm,0,-14,len,28);ctx.restore();}else{const ex=(sx+hx)/2+(front?face*5:-face*5),ey=(sy+hy)/2+7;drawLine(sx,sy,ex,ey,28,'#07111b');drawLine(sx,sy,ex,ey,18,'#194b67');drawLine(ex,ey,hx,hy,24,'#07111b');drawLine(ex,ey,hx,hy,14,'#efb58e');ctx.fillStyle='#efb58e';ctx.beginPath();ctx.arc(hx,hy,10,0,Math.PI*2);ctx.fill();}}limb(bsx,shoulder,bhx,bhy,false);limb(fsx,shoulder,fhx,fhy,true);drawHead(cx,headTop,duck?88:98,face);ctx.restore();ctx.globalAlpha=1;bar(P.x-14,P.y-34,108,P.hp/P.max,'#62ed8e');if(now()<P.shield){const rem=clamp((P.shield-now())/7600,0,1);ctx.strokeStyle=rem<.25?'#ffd45d':'#70efff';ctx.lineWidth=5;ctx.beginPath();ctx.arc(cx,P.y+62,78,-Math.PI/2,-Math.PI/2+Math.PI*2*rem);ctx.stroke();}}
function drawEntities(){for(const e of S.entities){if(e.k==='item'){const im=assets.get('item_'+e.type);if(im)ctx.drawImage(im,e.x,e.y,e.w,e.h);else{ctx.fillStyle='rgba(9,15,24,.82)';ctx.strokeStyle='#6eeaff';ctx.lineWidth=3;rr(e.x,e.y,e.w,e.h,8,true,true);text(e.type.toUpperCase(),e.x+e.w/2,e.y+33,12,'#fff','center');}}else if(e.k==='power'){const im=assets.get('power_'+e.type);if(im)ctx.drawImage(im,e.x,e.y,e.w,e.h);else{ctx.fillStyle='#12101c';ctx.strokeStyle='#ffe56e';ctx.lineWidth=3;rr(e.x,e.y,e.w,e.h,10,true,true);text(e.type==='shield'?'AR':e.type==='double'?'X2':'CP',e.x+e.w/2,e.y+40,18,'#ffe56e','center');}}else if(e.k==='enemy'){const sheet=assets.get('sheet_enemy'),sheetMeta=Q.customAssetMeta?.('spritesheets','enemy');if(sheet&&sheetMeta&&typeof Q.drawSpriteSheet==='function'&&Q.drawSpriteSheet(ctx,sheet,sheetMeta,e.variant==='low'?'low':'run',S.time+e.t,e.x,e.y,e.w,e.h,e.vx>=0?1:-1)){}else{ctx.fillStyle=e.variant==='low'?'#10202a':'#19141e';ctx.strokeStyle=e.variant==='low'?'#72eaff':'#ff6bd5';ctx.lineWidth=4;rr(e.x,e.y,e.w,e.h,10,true,true);text(e.variant==='low'?'LOW 8BIT':'8BIT',e.x+e.w/2,e.y+(e.variant==='low'?30:42),e.variant==='low'?11:13,e.variant==='low'?'#ffe56e':'#7eeaff','center');}}else if(e.k==='haz'){if(e.wait>0){const cd=e.m==='beam'?Math.max(1,Math.ceil(e.wait)):null;text(cd?`GLITCH IN ${cd}`:'! INCOMING !',e.x+e.w/2,e.y-18,cd?18:14,cd?'#ffdf65':'#ffd45d','center');ctx.strokeStyle=cd?'#ffdf65':'#ff4964';ctx.lineWidth=cd?5:3;ctx.setLineDash([10,8]);ctx.strokeRect(e.x-8,e.y-8,e.w+16,e.h+16);ctx.setLineDash([]);if(e.m==='beam'){ctx.globalAlpha=.18+.12*Math.sin(now()/80);ctx.fillStyle='#ff4f66';ctx.fillRect(e.x,e.y,e.w,e.h);ctx.globalAlpha=1;}continue;}const im=assets.get('hazard_'+Q.STAGES[S.stage].id);if(im&&e.m!=='beam')ctx.drawImage(im,e.x,e.y,e.w,e.h);else if(e.m==='beam'){ctx.shadowBlur=24;ctx.shadowColor='#ff3b61';ctx.fillStyle='rgba(255,45,80,.68)';ctx.fillRect(e.x,e.y,e.w,e.h);ctx.shadowBlur=0;}else{ctx.fillStyle='#3b1420';ctx.strokeStyle='#ff4964';ctx.lineWidth=4;rr(e.x,e.y,e.w,e.h,10,true,true);text(e.label,e.x+e.w/2,e.y+e.h/2,13,'#fff','center');}}else if(e.k==='bead'){ctx.shadowBlur=22;ctx.shadowColor='#66efff';ctx.fillStyle='#74f5ff';ctx.beginPath();ctx.arc(e.x+e.w/2,e.y+e.h/2,e.w*.43,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}}}
function drawShots(){for(const s of S.shots){ctx.shadowBlur=14;ctx.shadowColor=s.owner==='p'?'#ffe66c':'#ff536d';ctx.fillStyle=s.owner==='p'?'#ffe66c':'#ff536d';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}}
function drawBoss(){const b=S.boss;if(!b)return;const st=Q.STAGES[S.stage],sheetKey='boss'+st.id.charAt(0).toUpperCase()+st.id.slice(1),sheet=assets.get('sheet_'+sheetKey),sheetMeta=Q.customAssetMeta?.('spritesheets',sheetKey),im=assets.get('boss_'+st.id);if(sheet&&sheetMeta&&typeof Q.drawSpriteSheet==='function'&&Q.drawSpriteSheet(ctx,sheet,sheetMeta,b.warn>0?'charge':'idle',S.time,b.x-b.w/2,b.y-b.h/2,b.w,b.h,b.dir||-1)){}else if(im)ctx.drawImage(im,b.x-b.w/2,b.y-b.h/2,b.w,b.h);else{ctx.fillStyle='#12101a';ctx.strokeStyle=st.accent;ctx.lineWidth=6;rr(b.x-b.w/2,b.y-b.h/2,b.w,b.h,20,true,true);text(st.boss,b.x,b.y,18,'#fff','center');}bar(b.x-b.w/2,b.y-b.h/2-26,b.w,b.hp/b.max,'#ff5570');if(b.warn>0){text(b.label,b.x,b.y-b.h/2-50,16,'#ffe66c','center');ctx.strokeStyle='#ff5268';ctx.lineWidth=5;ctx.beginPath();ctx.arc(b.x,b.y,92,0,Math.PI*2);ctx.stroke();}}
function drawEnemyFighter(f){const sheet=assets.get('sheet_fighter'),sheetMeta=Q.customAssetMeta?.('spritesheets','fighter');if(sheet&&sheetMeta&&typeof Q.drawSpriteSheet==='function'){const state=f.stun>0?'hit':f.attack==='punch'?'punch':f.attack==='kick'?'kick':!f.ground?'jump':Math.abs(f.vx)>55?'walk':f.guard>0?'guard':'idle';if(Q.drawSpriteSheet(ctx,sheet,sheetMeta,state,S.time,f.x-62,f.y-4,124,158,f.face||-1))return;}let im=assets.get('fighter_enemy');if(f.stun>0)im=assets.get('fighter_enemyHit')||im;else if(f.attack==='punch')im=assets.get('fighter_enemyPunch')||im;else if(f.attack==='kick')im=assets.get('fighter_enemyKick')||im;if(im){ctx.drawImage(im,f.x-60,f.y-4,120,158);return;}const prog=f.attack?clamp((now()-f.attackT)/f.attackLen,0,1):0,pn=f.attack==='punch'?Math.sin(prog*Math.PI):0,kk=f.attack==='kick'?Math.sin(prog*Math.PI):0,d=f.face||-1,hip=f.y+102,shoulder=f.y+53;drawLine(f.x-18,hip,f.x-25-d*8,f.y+145,30,'#140e16');drawLine(f.x-18,hip,f.x-25-d*8,f.y+145,19,'#6a3740');const kx=f.x+18+d*(22+72*kk),ky=f.y+143-38*kk;drawLine(f.x+18,hip,kx,ky,30,'#140e16');drawLine(f.x+18,hip,kx,ky,19,'#7d4248');ctx.fillStyle=f.guard>0?'#46657b':'#7b3c48';ctx.strokeStyle='#160f18';ctx.lineWidth=7;rr(f.x-45,f.y+42,90,75,18,true,true);ctx.fillStyle='#d6a075';ctx.beginPath();ctx.arc(f.x,f.y+25,30,0,Math.PI*2);ctx.fill();const hx=f.x+d*(48+58*pn);drawLine(f.x+d*34,shoulder,hx,shoulder+3,24,'#d6a075');drawLine(f.x-d*34,shoulder,f.x-d*52,shoulder+36,24,'#d6a075');text('TIER-TEX',f.x,f.y+84,13,'#fff','center');}
function drawFighter(){bg('fighter');drawPlayer();drawEnemyFighter(S.fighter);foreground('fighter');bar(S.fighter.x-52,S.fighter.y-28,104,S.fighter.hp/S.fighter.max,'#ff6a62');text('36% CONVERSION BOUT',800,88,28,'#ffe56e','center');text('Z/CTRL PUNCH   X/C KICK   ↓ DUCK   SPACE JUMP',800,125,15,'#fff','center');text(`AI: ${String(S.fighter.ai||'read').toUpperCase()}   TIMER ${Math.ceil(S.fighter.boutTime)}`,800,154,14,'#7eeaff','center');if(S.fighter.messageT>0)text(S.fighter.message,800,188,18,'#ffcf68','center');}
function drawInvaders(){bg('invaders');const g=S.inv,textPulse=Math.floor(g.elapsed*5)%2;text('ALIEN FORMATION',800,62,28,'#72eaff','center');ctx.save();ctx.globalAlpha=.28;ctx.strokeStyle='#274a78';ctx.lineWidth=1;for(let y=520;y<820;y+=38){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(Q.W,y);ctx.stroke();}for(let x=0;x<Q.W;x+=80){ctx.beginPath();ctx.moveTo(800,520);ctx.lineTo(x,820);ctx.stroke();}ctx.restore();for(let i=0;i<105;i++){ctx.fillStyle=i%4?'rgba(255,255,255,.28)':'rgba(114,234,255,.55)';const tw=1+(i%7===textPulse?1:0);ctx.fillRect((i*227)%1600,(i*131)%690,tw,tw);}for(const b of g.bunkers||[]){if(b.hp<=0)continue;const im=assets.get('invader_bunker');if(im)ctx.drawImage(im,b.x-b.w/2,b.y,b.w,b.h);else{ctx.fillStyle='#143b36';ctx.strokeStyle='#7df0a5';ctx.lineWidth=3;rr(b.x-b.w/2,b.y,b.w,b.h,8,true,true);for(let i=0;i<b.max-b.hp;i++){ctx.fillStyle='#07111b';ctx.fillRect(b.x-b.w/2+12+i*13,b.y+5,8,24);}}bar(b.x-b.w/2,b.y+b.h+5,b.w,b.hp/b.max,'#7df0a5');}for(const a of g.aliens.filter(x=>x.alive)){const im=assets.get('invader_alien'+(a.row+1));if(im){ctx.drawImage(im,a.x,a.y,a.w,a.h);continue;}const c=['#7df0a5','#ffe56e','#ff8fc9','#72eaff','#a98cff'][a.row%5],wiggle=Math.sin(a.phase)>0?4:-4;ctx.fillStyle=c;ctx.strokeStyle='#070b12';ctx.lineWidth=4;rr(a.x+5,a.y+4,a.w-10,a.h-8,8,true,true);ctx.fillStyle='#07111b';ctx.fillRect(a.x+14,a.y+12,7,7);ctx.fillRect(a.x+a.w-21,a.y+12,7,7);ctx.strokeStyle=c;ctx.lineWidth=5;drawLine(a.x+14,a.y+a.h-5,a.x+11+wiggle,a.y+a.h+8,5,c);drawLine(a.x+a.w-14,a.y+a.h-5,a.x+a.w-11-wiggle,a.y+a.h+8,5,c);}const ship=assets.get('invader_ship');if(ship)ctx.drawImage(ship,g.shipX-52,770,104,65);else{ctx.shadowBlur=18;ctx.shadowColor='#72eaff';ctx.fillStyle='#72eaff';ctx.beginPath();ctx.moveTo(g.shipX,765);ctx.lineTo(g.shipX-50,825);ctx.lineTo(g.shipX-20,817);ctx.lineTo(g.shipX,790);ctx.lineTo(g.shipX+20,817);ctx.lineTo(g.shipX+50,825);ctx.closePath();ctx.fill();ctx.shadowBlur=0;text('CCG',g.shipX,812,12,'#07111b','center');}for(const sh of g.shots){const im=assets.get(sh.owner==='p'?'invader_playerShot':'invader_enemyShot');if(im)ctx.drawImage(im,sh.x-8,sh.y-12,16,24);else{ctx.shadowBlur=10;ctx.shadowColor=sh.owner==='p'?'#ffe56e':'#ff6174';ctx.fillStyle=sh.owner==='p'?'#ffe56e':'#ff6174';ctx.fillRect(sh.x-3,sh.y-10,6,20);ctx.shadowBlur=0;}}text(`SHIELDS ${'■'.repeat(Math.max(0,g.shield))}`,60,850,16,'#7df0a5');text(`ALIENS ${g.aliens.filter(a=>a.alive).length}`,1540,850,16,'#fff','right');foreground('invaders');}
function drawMaze(){bg('maze');const m=S.maze,cell=54,ox=(Q.W-m.W*cell)/2,oy=105;text('DOT-MAZE RUN',800,62,28,'#ffe56e','center');for(let y=0;y<m.H;y++)for(let x=0;x<m.W;x++){const px=ox+x*cell,py=oy+y*cell,k=`${x},${y}`;if(m.walls.has(k)){ctx.fillStyle='#151653';ctx.strokeStyle='#6b72ff';ctx.lineWidth=2;rr(px+2,py+2,cell-4,cell-4,8,true,true);}else if(m.dots.has(k)){ctx.fillStyle=m.power.has(k)?'#ffe56e':'#f2e7ff';ctx.beginPath();ctx.arc(px+cell/2,py+cell/2,m.power.has(k)?8:3,0,Math.PI*2);ctx.fill();}}const pcx=ox+m.px*cell+cell/2,pcy=oy+m.py*cell+cell/2;ctx.fillStyle='#ffd84d';ctx.beginPath();ctx.arc(pcx,pcy,19,0,Math.PI*2);ctx.fill();drawHead(pcx,pcy-20,40,1);for(const e of m.enemies){const ex=ox+e.x*cell+8,ey=oy+e.y*cell+8,cols={hunter:'#ff5f86',ambush:'#ff9f5f',pincer:'#d56dff',guard:'#58d6ff'};ctx.fillStyle=m.powered>0?'#4b7cff':cols[e.role]||'#ff5f86';ctx.strokeStyle='#fff';ctx.lineWidth=2;rr(ex,ey,cell-16,cell-16,8,true,true);text(e.role==='hunter'?'H':e.role==='ambush'?'A':e.role==='pincer'?'P':'G',ex+(cell-16)/2,ey+25,12,'#fff','center');}text(`DOTS ${m.collected}/${m.target}`,60,850,16,'#fff');text(`ENERGY ${Math.max(0,P.hp)}`,800,850,15,P.hp<35?'#ff6174':'#7df0a5','center');bar(690,860,220,P.hp/P.max,P.hp<35?'#ff6174':'#7df0a5');if(m.powered>0)text(`BUG SLOW ${m.powered.toFixed(1)}s — CONTACT STILL HURTS`,1540,850,14,'#72eaff','right');foreground('maze');}
function stageNextLabel(){if(S.stage===0)return'ELECTRIC BEAD RUN';if(S.stage===1)return'36% CONVERSION BOUT';if(S.stage===2)return'DOT-MAZE RUN';if(S.stage===3)return'GURU MEDITATION';return'FINAL BOSS';}
function drawHUD(){ctx.fillStyle='rgba(4,4,12,.82)';ctx.fillRect(0,0,Q.W,82);text(`SCORE ${Q.fmt(S.score)}`,24,31,18);text(`LIVES ${'♥'.repeat(Math.max(0,S.lives))}`,24,59,16,'#ff7690');let title=Q.STAGES[S.stage]?.name||'',progress=0,status='';if(S.mode==='beads'){title='ELECTRIC BEAD RUN';progress=clamp(S.beadTime/28,0,1);status=`BEAD RUN ${Math.max(0,Math.ceil(28-S.beadTime))}s`; }else if(S.mode==='fighter'){title='36% BOUT';progress=1-S.fighter.boutTime/45;status='WIN TO REACH ALIEN FORMATION';}else if(S.mode==='invaders'){title='ALIEN FORMATION';progress=1-S.inv.aliens.filter(a=>a.alive).length/S.inv.aliens.length;status='CLEAR THE FORMATION TO REACH CHRISTMAS';}else if(S.mode==='maze'){title='DOT-MAZE RUN';progress=S.maze.collected/S.maze.target;status='CLEAR 110 DOTS TO REACH AMIGA';}else if(S.mode==='stage'){const d=Q.STAGES[S.stage].duration;progress=clamp(S.elapsed/d,0,1);status=`NEXT: ${stageNextLabel()} IN ${Math.max(0,Math.ceil(d-S.elapsed))}s`;}else if(S.mode==='boss'){progress=S.boss?1-S.boss.hp/S.boss.max:0;status='BOSS PHASE — DEFEAT IT TO CONTINUE';}text(title,800,31,19,'#7eeaff','center');text(`BEST ${Q.fmt(S.best)}`,1570,31,17,'#fff','right');text(`RANK ${ACH.rank()}`,1570,58,13,'#ffd45d','right');if(['stage','boss','beads','fighter','invaders','maze'].includes(S.mode)){ctx.fillStyle='#171525';ctx.fillRect(330,66,940,8);ctx.fillStyle='#72eaff';ctx.fillRect(330,66,940*clamp(progress,0,1),8);text(status,800,60,12,'#d7d8e8','center');}if(now()<P.shield)text(`ACTION REPLAY ${Math.max(0,(P.shield-now())/1000).toFixed(1)}s`,800,80,12,'#78efff','center');}
function particlesDraw(){for(const p of S.particles){ctx.globalAlpha=clamp(p.life,0,1);if(p.kind==='dot'){ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}else text(p.t,p.x,p.y,16,p.c,'center');}ctx.globalAlpha=1;}
function button(x,y,w,h,label,fn,danger=false){ctx.fillStyle=danger?'#32101a':'#111223';ctx.strokeStyle=danger?'#ff6174':'#68e7ff';ctx.lineWidth=3;rr(x,y,w,h,10,true,true);text(label,x+w/2,y+h/2+7,17,danger?'#ff9aaa':'#fff','center');S.buttons.push({x,y,w,h,fn});}
function title(){S.buttons=[];bg('bedroom');ctx.fillStyle='rgba(0,0,0,.58)';ctx.fillRect(0,0,Q.W,Q.H);text("CHEEKY'S COMMODORE QUEST",800,210,54,'#72eaff','center',900);text('C64 / AMIGA ARCADE PARODY',800,260,21,'#ffe56e','center');drawHead(800,295,130,1);if(assets.get('player_avatar'))text('SIGNED-IN AVATAR HEAD ACTIVE',800,450,13,'#7df0a5','center');button(590,485,420,62,'START QUEST',startQuest);button(590,565,420,58,'LEVEL SELECT',()=>mode('levels'));button(590,640,420,58,'ACHIEVEMENTS',()=>mode('achievements'));text('MOVE A/D OR ←/→   JUMP SPACE   DUCK S/↓   FIRE Z/CTRL',800,750,14,'#ddd','center');}
function levels(){S.buttons=[];ctx.fillStyle='#080713';ctx.fillRect(0,0,Q.W,Q.H);text('LEVEL SELECT',800,70,40,'#72eaff','center');Q.LEVELS.forEach(([id,label],i)=>{const col=i%3,row=Math.floor(i/3);button(120+col*505,140+row*105,465,70,label.toUpperCase(),()=>practice(id));});button(650,725,300,52,'BACK',()=>mode('title'));}
function achievementScreen(){S.buttons=[];ctx.fillStyle='#080713';ctx.fillRect(0,0,Q.W,Q.H);text('CCG ACHIEVEMENTS',800,65,40,'#72eaff','center');ACH.entries().forEach((a,i)=>{const c=i%4,r=Math.floor(i/4),x=45+c*385,y=105+r*98;ctx.fillStyle=a.done?'rgba(45,130,80,.26)':'rgba(15,16,29,.9)';ctx.strokeStyle=a.done?'#78efa4':'#555a6d';rr(x,y,355,82,10,true,true);text(`${a.done?'✓ ':''}${a.name}`,x+12,y+24,13,a.done?'#8cffb5':'#fff');text(a.desc.slice(0,43),x+12,y+45,10,'#adb1c2');text(`${Math.min(a.value,a.target)}/${a.target}`,x+335,y+68,10,'#ffd45d','right');});button(650,805,300,45,'BACK',()=>mode('title'));}
function drawStage(){const id=Q.STAGES[S.stage]?.id||'bedroom';bg(id);drawEntities();drawShots();drawPlayer();if(S.mode==='boss')drawBoss();foreground(id);drawHUD();}
function drawBeads(){bg('beads');drawEntities();drawShots();drawPlayer();foreground('beads');drawHUD();}
function overlay(){if(S.mode==='transition'){ctx.fillStyle='rgba(0,0,0,.68)';ctx.fillRect(0,0,Q.W,Q.H);text(S.transition.title,800,410,48,'#72eaff','center');text(S.transition.sub,800,465,20,'#ffe56e','center');}else if(S.mode==='pause'||S.mode==='quit'){S.buttons=[];ctx.fillStyle='rgba(0,0,0,.65)';ctx.fillRect(0,0,Q.W,Q.H);text(S.mode==='pause'?'PAUSED':'ABANDON THIS RUN?',800,300,52,S.mode==='pause'?'#72eaff':'#ff7183','center');button(590,375,420,58,'RESUME',()=>mode(S.returnMode));if(S.mode==='pause')button(590,450,420,58,'LEVEL SELECT',()=>mode('levels'));button(590,S.mode==='pause'?525:460,420,58,'QUIT TO TITLE',quit,true);}else if(S.mode==='over'||S.mode==='won'){S.buttons=[];ctx.fillStyle='rgba(0,0,0,.74)';ctx.fillRect(0,0,Q.W,Q.H);text(S.mode==='won'?'COMMODORE QUEST COMPLETE':'GAME OVER',800,280,54,S.mode==='won'?'#7df0a5':'#ff7183','center');text(`SCORE ${Q.fmt(S.score)}`,800,350,30,'#fff','center');button(535,420,250,60,'PLAY AGAIN',startQuest);button(815,420,250,60,'LEVEL SELECT',()=>mode('levels'));button(675,505,250,54,'TITLE',quit);}}
function draw(){ctx.save();const sh=S.shake;ctx.translate(sh?rand(-sh,sh):0,sh?rand(-sh,sh):0);if(S.mode==='title')title();else if(S.mode==='levels')levels();else if(S.mode==='achievements')achievementScreen();else if(S.mode==='fighter'){drawFighter();drawHUD();}else if(S.mode==='beads')drawBeads();else if(S.mode==='invaders'){drawInvaders();drawHUD();}else if(S.mode==='maze'){drawMaze();drawHUD();}else drawStage();particlesDraw();if(S.toast&&now()<S.toast.until){ctx.fillStyle='rgba(4,8,15,.94)';ctx.strokeStyle='#ffd45d';ctx.lineWidth=3;rr(1080,760,470,105,12,true,true);text('ACHIEVEMENT UNLOCKED',1100,790,13,'#ffd45d');text(S.toast.text,1100,820,19);text('+'+S.toast.xp+' CCG XP',1100,846,13,'#7ff0a4');}overlay();ctx.restore();if(S.flash>0){ctx.globalAlpha=S.flash;ctx.fillStyle='#ff4964';ctx.fillRect(0,0,Q.W,Q.H);ctx.globalAlpha=1;}ctx.globalAlpha=.07;ctx.fillStyle='#000';for(let y=0;y<Q.H;y+=4)ctx.fillRect(0,y,Q.W,1);ctx.globalAlpha=1;}
function gameOver(){mode('over');if(!S.practice)ACH.save();}function win(){if(!S.practice){ACH.flag('won');if(S.lives===3)ACH.flag('oneCredit');}mode('won');}function quit(){audio.setTheme(0,false,'title');reset();mode('title');}
function pointer(ev){const r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)*Q.W/r.width,y:(ev.clientY-r.top)*Q.H/r.height};}canvas.addEventListener('pointerdown',e=>{focus();const p=pointer(e);for(let i=S.buttons.length-1;i>=0;i--){const b=S.buttons[i];if(p.x>=b.x&&p.x<=b.x+b.w&&p.y>=b.y&&p.y<=b.y+b.h){b.fn();break;}}});function pause(){if(['stage','boss','beads','fighter','invaders','maze','transition'].includes(S.mode)){S.returnMode=S.mode;mode('pause');}else if(S.mode==='pause')mode(S.returnMode);}document.getElementById('btn-pause').onclick=pause;document.getElementById('btn-level').onclick=()=>mode('levels');document.getElementById('btn-quit').onclick=()=>{if(S.mode==='title')return;S.returnMode=S.mode;mode('quit');};document.getElementById('btn-fullscreen').onclick=()=>{const sh=document.getElementById('game-shell');document.fullscreenElement?document.exitFullscreen?.():sh.requestFullscreen?.();focus();};document.querySelectorAll('[data-touch]').forEach(b=>{const n=b.dataset.touch;['pointerdown','touchstart'].forEach(ev=>b.addEventListener(ev,e=>{e.preventDefault();input.setVirtual(n,true);}));['pointerup','pointercancel','pointerleave','touchend'].forEach(ev=>b.addEventListener(ev,e=>{e.preventDefault();input.setVirtual(n,false);}));});addEventListener('keydown',e=>{if(e.code==='Escape')pause();});
function loop(t){const dt=Math.min(.033,(t-S.last)/1000||0);S.last=t;if(!['title','levels','achievements','pause','quit','over','won','loading'].includes(S.mode))update(dt);draw();input.clear();requestAnimationFrame(loop);}window.CCGQuestDebug={startQuest,practice,getState:()=>({mode:S.mode,stage:S.stage,score:S.score,player:{x:P.x,y:P.y,hp:P.hp,duck:P.duck},boss:S.boss&&{x:S.boss.x,y:S.boss.y,hp:S.boss.hp},fighter:S.fighter&&{x:S.fighter.x,hp:S.fighter.hp,ai:S.fighter.ai},invaders:S.inv&&{alive:S.inv.aliens.filter(a=>a.alive).length,shield:S.inv.shield},maze:S.maze&&{dots:S.maze.collected,target:S.maze.target,powered:S.maze.powered}})};
Promise.resolve(Q.hydrateRemoteAssets?.()).catch(()=>false).then(load).then(()=>{loading.classList.add('is-hidden');audio.setTheme(0,false,'title');mode('title');requestAnimationFrame(loop);}).catch(e=>{loading.textContent='LOAD ERROR: '+e.message;console.error(e);});
})();
